/// <summary>
/// Continuing permission notice report controller
/// Class <c>METPOContinuingPermissionNoticeController</c> controller
/// </summary>
class METPOContinuingPermissionNoticeController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// constructor creates the instance for class
/// </summary>
/// <returns>constructor</returns>
public static METPOContinuingPermissionNoticeController construct()
{
    return new METPOContinuingPermissionNoticeController();
}

/// <summary>
/// Update the contract class parameters.
/// </summary>
protected void prePromptModifyContract()
{
    METPOContinuingPermissionNoticeContract contract = this.parmReportContract().parmRdpContract() as METPOContinuingPermissionNoticeContract;
    Args parmArgs =  this.parmArgs();
    PurchTable purchTable;
    VendInvoiceJour vendInvoiceJour;

    if (parmArgs.dataset() == tableNum(VendInvoiceJour))
    {
        vendInvoiceJour = parmArgs.record();
        purchTable = PurchTable::find(vendInvoiceJour.PurchId);
    }
    else if (parmArgs.dataset() == tableNum(PurchTable))
    {
        purchTable = parmArgs.record();
    }

    contract = this.parmReportContract().parmRdpContract();

    contract.parmPurchId(purchTable.PurchId);

    if (parmArgs.menuItemName() == menuItemOutputStr(METPOContinuingPermissionNotice))
    {
        contract.parmIsRePrint(true);
    }
    else
    {
        contract.parmIsRePrint(false);
    }
}

/// <summary>
/// Main method to run report
/// </summary>
/// <param name = "_args">_args</param>
static void main(Args _args)
{
    METPOContinuingPermissionNoticeController controller =
        METPOContinuingPermissionNoticeController::construct();

    PrintMgmtDocumentType type =  PrintMgmtDocumentType::METPOContinuingPermissionNote;
    PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findSystem(type);

    if (!printMgmtReportFormat.RecId)
    {
        select Name from printMgmtReportFormat
            where printMgmtReportFormat.DocumentType == type;
    }

    controller.parmReportName(printMgmtReportFormat.Name);
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    controller.parmDialogCaption("@MET:METCPNotice");
    controller.startOperation();
}
